class CustomLogBuffer : public std::streambuf {
protected:
    int_type overflow(int_type c) override {
        // Advanced: Log 'c' to a custom backend (DB, network)
        if (c != traits_type::eof()) {
            // Implementation detail omitted
        }
        return traits_type::not_eof(c);
    }
};

// Redirect clog to use the custom buffer
CustomLogBuffer clb;
std::streambuf* old_clog_buf = std::clog.rdbuf(&clb);

// Performance optimization: Untie input from output
std::cin.tie(nullptr);

// Performance optimization: Disable C stdio synchronization
std::ios_base::sync_with_stdio(false);

// Restore original buffer
std::clog.rdbuf(old_clog_buf);
